   318→                for (let j = 0; j < windowFrames.length; j++) {
   319→                    flattenedMel.set(windowFrames[j], j * 32);
   320→                }
   321→
   322→                const embeddingFeeds = { [this._embeddingModel.inputNames[0]]: new ort.Tensor('float32', flattenedMel, [1, 76, 32, 1]) };
