   324→                const newEmbedding = embeddingOut[this._embeddingModel.outputNames[0]].data;
   325→
   326→                const embeddingVector = new Float32Array(newEmbedding);
   327→
   328→                for (const name of Object.keys(this._keywordModels)) {
   329→                    const keywordModel = this._keywordModels[name];
