   338→                    const results = await keywordModel.session.run({ [keywordModel.session.inputNames[0]]: finalInput });
   339→                    const score = results[keywordModel.session.outputNames[0]].data[0];
   340→                    keywordModel.scores.shift();
   341→                    keywordModel.scores.push(score);
   342→                    this._debug('Keyword score', { keyword: name, score: Number(score.toFixed(3)), windowSize: keywordModel.windowSize });
   343→
   344→                    const keywordActive = this._activeKeywords.has(name);
   345→                    if (emitEvents && keywordActive && score > this.config.detectionThreshold && isSpeechActive && !this._isDetectionCoolingDown) {
   346→                        this._isDetectionCoolingDown = true;
   347→                        this._debug('Detection emitted', { keyword: name, score });
   348→                        this._emitter.emit('detect', { keyword: name, score, at: performance.now() });
   349→                        setTimeout(() => { this._isDetectionCoolingDown = false; }, this.config.cooldownMs);
   350→                    } else if (emitEvents && !keywordActive) {
   351→                        this._debug('Detection suppressed (inactive keyword)', { keyword: name, score });
   352→                    }
   353→                }
