   355→            }
   356→        }
   357→
   358→        _setOrtPath(path) {
   359→            if (path && typeof ort !== 'undefined') {
   360→                ort.env.wasm.wasmPaths = path;
   361→            }
   362→        }
   363→
   364→        _inferKeywordWindowSize(session) {
   365→            if (!session) return undefined;
   366→            const metadata = session.inputMetadata;
   367→            const inputName = session.inputNames?.[0];
   368→            if (!metadata || !inputName) return undefined;
   369→            let meta;
   370→            if (Array.isArray(metadata)) {
   371→                meta = metadata.find((m) => m?.name === inputName) || metadata[0];
   372→            } else {
   373→                meta = metadata[inputName];
   374→            }
   375→            if (!meta || !meta.isTensor || !Array.isArray(meta.shape)) return undefined;
