   381→            if (this.config.debug) {
   382→                console.debug('[WakeWordEngine]', ...args);
   383→            }
   384→        }
   385→
   386→        setActiveKeywords(keywords) {
   387→            const next = Array.isArray(keywords) && keywords.length ? keywords : this.config.keywords;
   388→            this._activeKeywords = new Set(next);
   389→            this._debug('Active keywords updated', Array.from(this._activeKeywords));
   390→        }
   391→    }
